 const tokenData=await tokenResponse.json();
 if(!tokenResponse.ok||!tokenData.access_token) throw new Error("GMAIL_TOKEN_REFRESH_FAILED");
 const isFrench=String(language||"ar").toLowerCase().startsWith("fr");
 const accessUrl=["ADMIN","SUPPORT"].includes(assignedRole)?"https://houssem028.github.io/beru-ai/admin.html":"https://houssem028.github.io/beru-ai/team.html";
