        const stateHash=await hashToken(state); const saved=await env.DB.prepare("SELECT admin_id,expires_at,used_at FROM beru_gmail_oauth_states WHERE state_hash=?").bind(stateHash).first();
        if(!saved || saved.used_at || Date.parse(saved.expires_at)<=Date.now()) return new Response("This Gmail connection link is invalid or expired. Return to BERU ADMIN and try again.",{status:400,headers:{"Content-Type":"text/plain; charset=utf-8","Cache-Control":"no-store"}});
        const consumed=await env.DB.prepare("UPDATE beru_gmail_oauth_states SET used_at=CURRENT_TIMESTAMP WHERE state_hash=? AND used_at IS NULL AND expires_at>?").bind(stateHash,new Date().toISOString()).run();
        if(!(consumed.meta?.changes>0)) return new Response("This Gmail connection link has already been used.",{status:409,headers:{"Content-Type":"text/plain; charset=utf-8","Cache-Control":"no-store"}});
        const tokenResponse=await fetch("https://oauth2.googleapis.com/token",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams({code:codeValue,client_id:"1029198003465-bs891ka49b1j2a1rm5m60cnog5vtalm3.apps.googleusercontent.com",client_secret:env.GOOGLE_CLIENT_SECRET,redirect_uri:"https://beru-admin-engine.mmzhoussem.workers.dev/oauth/gmail/callback",grant_type:"authorization_code"})});
