        await env.DB.prepare("INSERT INTO beru_gmail_config (id,refresh_token_ciphertext,refresh_token_iv,sender_email,connected_by_admin_id,connected_at,updated_at) VALUES (1,?,?,NULL,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(id) DO UPDATE SET refresh_token_ciphertext=excluded.refresh_token_ciphertext,refresh_token_iv=excluded.refresh_token_iv,connected_by_admin_id=excluded.connected_by_admin_id,connected_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP").bind(encrypted.ciphertext,encrypted.iv,saved.admin_id).run();
