        const recent = await env.DB.prepare("SELECT id FROM admin_logs WHERE admin_id=? AND action='GMAIL_TEST_ATTEMPT' AND created_at >= datetime('now','-1 minute') ORDER BY id DESC LIMIT 1").bind(admin.id).first();
